<?php
declare(strict_types=1);ob_start(static fn(string $html):string=>str_replace('</body>','<script src="../../public/js/dance-cup-judge-order.js?v=320"></script></body>',$html));require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;Auth::requireAdmin();$pdo=Database::connection();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin required.');}try{DanceCupScoringService::ensureWorkspaceTables($pdo,$test);}catch(Throwable $e){http_response_code(503);exit('Dance Cup scoring setup is incomplete. Run the database migration for this release, then reload.');}$t=DanceCupScoringService::tables($test);$p=$test?'bdc_test_dance_cup':'bdc_dance_cup';$id=(int)($_GET['id']??$_POST['id']??0);$error='';$notice='';
function dcSnapshot(PDO $pdo,string $p,int $id):array{$out=[];$tables=['entries'=>"{$p}_entries",'judges'=>"{$p}_judges",'marks'=>"{$p}_marks",'results'=>"{$p}_scoring_results"];foreach($tables as $name=>$table){$q=$pdo->prepare("SELECT * FROM {$table} WHERE competition_id=:id");$q->execute(['id'=>$id]);$out[$name]=$q->fetchAll();}return $out;}
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');$status=$pdo->prepare("SELECT status FROM {$t['competitions']} WHERE id=:id");$status->execute(['id'=>$id]);$locked=$status->fetchColumn()==='submitted';if($locked&&!in_array($action,['checkpoint'],true))throw new RuntimeException('Competition is submitted and locked.');if($action==='add_competitor'){$name=trim((string)($_POST['display_name']??''));$bib=(int)($_POST['bib_number']??0);if($name===''||$bib<1)throw new RuntimeException('Competitor name and bib are required.');$q=$pdo->prepare("INSERT INTO {$p}_entries(competition_id,bib_number,display_name) VALUES(:c,:b,:n)");$q->execute(['c'=>$id,'b'=>$bib,'n'=>$name]);$notice='Competitor added.';}elseif($action==='add_judge'){$name=trim((string)($_POST['judge_name']??''));if($name==='')throw new RuntimeException('Judge name is required.');$q=$pdo->prepare("INSERT INTO {$p}_judges(competition_id,judge_name,judge_order,is_chief) VALUES(:c,:n,(SELECT COALESCE(MAX(x.judge_order),0)+1 FROM {$p}_judges x WHERE x.competition_id=:c2),:chief)");$q->execute(['c'=>$id,'n'=>$name,'c2'=>$id,'chief'=>!empty($_POST['is_chief'])?1:0]);$notice='Judge added.';}elseif($action==='save_scores'){$marks=(array)($_POST['mark']??[]);$criteria=$pdo->prepare("SELECT id,maximum_points FROM {$t['criteria']} WHERE competition_id=:id");$criteria->execute(['id'=>$id]);$limits=[];foreach($criteria->fetchAll() as $x)$limits[(int)$x['id']]=(float)$x['maximum_points'];$up=$pdo->prepare("INSERT INTO {$p}_marks(competition_id,entry_id,judge_id,criterion_id,points) VALUES(:c,:e,:j,:criterion,:p) ON DUPLICATE KEY UPDATE points=VALUES(points),updated_at=NOW()");foreach($marks as $entry=>$judges)foreach((array)$judges as $judge=>$values)foreach((array)$values as $criterion=>$points){$criterion=(int)$criterion;$points=(float)$points;if(!isset($limits[$criterion])||$points<0||$points>$limits[$criterion])throw new RuntimeException('A mark is outside its criterion maximum.');$up->execute(['c'=>$id,'e'=>(int)$entry,'j'=>(int)$judge,'criterion'=>$criterion,'p'=>$points]);}$notice='Score draft saved.';}elseif($action==='calculate'){$q=$pdo->prepare("SELECT e.id,COALESCE(SUM(m.points),0) total FROM {$p}_entries e LEFT JOIN {$p}_marks m ON m.entry_id=e.id AND m.competition_id=e.competition_id WHERE e.competition_id=:id AND e.status='active' GROUP BY e.id ORDER BY total DESC,e.bib_number");$q->execute(['id'=>$id]);$rows=$q->fetchAll();$pdo->beginTransaction();$pdo->prepare("DELETE FROM {$p}_scoring_results WHERE competition_id=:id")->execute(['id'=>$id]);$up=$pdo->prepare("INSERT INTO {$p}_scoring_results(competition_id,entry_id,total_score,placement) VALUES(:c,:e,:t,:p)");$place=0;$last=null;foreach($rows as $i=>$r){$total=(float)$r['total'];if($last===null||$total<$last)$place=$i+1;$up->execute(['c'=>$id,'e'=>$r['id'],'t'=>$total,'p'=>$place]);$last=$total;}$pdo->commit();$notice='Totals calculated and ranked.';}elseif($action==='checkpoint'){$label=trim((string)($_POST['checkpoint_label']??''))?:'Manual checkpoint '.date('Y-m-d H:i');$q=$pdo->prepare("INSERT INTO {$p}_checkpoints(competition_id,label,snapshot_json,created_by) VALUES(:c,:l,:s,:u)");$q->execute(['c'=>$id,'l'=>$label,'s'=>json_encode(dcSnapshot($pdo,$p,$id),JSON_UNESCAPED_SLASHES),'u'=>(int)(Auth::user()['id']??0)?:null]);$notice='Checkpoint saved.';}elseif($action==='submit'){$count=$pdo->prepare("SELECT COUNT(*) FROM {$p}_scoring_results WHERE competition_id=:id");$count->execute(['id'=>$id]);if((int)$count->fetchColumn()<1)throw new RuntimeException('Calculate and review results before submitting.');$pdo->prepare("UPDATE {$t['competitions']} SET status='submitted' WHERE id=:id")->execute(['id'=>$id]);$notice='Competition submitted and locked.';}}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$q=$pdo->prepare("SELECT c.*,e.name event_name,e.event_date FROM {$t['competitions']} c JOIN {$t['events']} e ON e.id=c.event_id WHERE c.id=:id");$q->execute(['id'=>$id]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Dance Cup category not found.');}$q=$pdo->prepare("SELECT * FROM {$t['criteria']} WHERE competition_id=:id ORDER BY sort_order,id");$q->execute(['id'=>$id]);$criteria=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_entries WHERE competition_id=:id AND status='active' ORDER BY bib_number");$q->execute(['id'=>$id]);$entries=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_judges WHERE competition_id=:id ORDER BY judge_order,id");$q->execute(['id'=>$id]);$judges=$q->fetchAll();$q=$pdo->prepare("SELECT entry_id,judge_id,criterion_id,points FROM {$p}_marks WHERE competition_id=:id");$q->execute(['id'=>$id]);$marks=[];foreach($q->fetchAll() as $m)$marks[(int)$m['entry_id']][(int)$m['judge_id']][(int)$m['criterion_id']]=$m['points'];$q=$pdo->prepare("SELECT r.*,e.bib_number,e.display_name FROM {$p}_scoring_results r JOIN {$p}_entries e ON e.id=r.entry_id WHERE r.competition_id=:id ORDER BY r.placement,e.bib_number");$q->execute(['id'=>$id]);$results=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_checkpoints WHERE competition_id=:id ORDER BY id DESC LIMIT 10");$q->execute(['id'=>$id]);$checkpoints=$q->fetchAll();$csrf=Csrf::token();$locked=$c['status']==='submitted';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['category_name'])?> | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=318" rel="stylesheet"><style>@media print{.no-print,form,nav{display:none!important}.card{box-shadow:none!important}.score-input{border:0!important}}.score-input{min-width:76px}.sticky-actions{position:sticky;bottom:0;background:#fff;padding:12px;z-index:3}</style></head><body class="bg-light"><main class="container-fluid py-4" style="max-width:1600px"><div class="no-print"><a href="./<?=$test?'?data_mode=test':''?>">← Dance Cup Dashboard</a></div><section class="card border-0 shadow-sm mt-3"><div class="card-body p-4"><span class="badge <?=$locked?'text-bg-success':'text-bg-secondary'?>"><?=e(strtoupper($c['status']))?></span><h1 class="h3 mt-2"><?=e($c['category_name'])?></h1><p class="text-muted"><?=e($c['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?> · <?=e(ucwords(str_replace('_',' ',$c['competition_level'])))?> · <?=e(ucfirst($c['entry_type']))?></p><?php if($notice):?><div class="alert alert-success no-print"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger no-print"><?=e($error)?></div><?php endif;?>
<div class="row g-3 no-print"><div class="col-lg-6"><div class="border rounded p-3"><h2 class="h5">Add Competitor</h2><form method="post" class="row g-2"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="add_competitor"><div class="col-3"><input class="form-control" type="number" min="1" name="bib_number" placeholder="Bib" required></div><div class="col"><input class="form-control" name="display_name" placeholder="Competitor or team name" required></div><div class="col-auto"><button class="btn btn-primary" <?=$locked?'disabled':''?>>Add</button></div></form></div></div><div class="col-lg-6"><div class="border rounded p-3"><h2 class="h5">Add Judge</h2><form method="post" class="row g-2"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="add_judge"><div class="col"><input class="form-control" name="judge_name" placeholder="Judge name" required></div><div class="col-auto form-check mt-2"><input class="form-check-input" type="checkbox" name="is_chief" id="chief"><label for="chief">Chief</label></div><div class="col-auto"><button class="btn btn-dark" <?=$locked?'disabled':''?>>Add</button></div></form></div></div></div>
<h2 class="h5 mt-4">Judge Scoring Sheet</h2><?php if(!$entries||!$judges):?><div class="alert alert-warning no-print">Add competitors and judges to begin scoring.</div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="save_scores"><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>Bib / Competitor</th><th>Judge</th><?php foreach($criteria as $x):?><th><?=e($x['criterion_name'])?><small class="d-block text-muted">/ <?=number_format((float)$x['maximum_points'],2)?></small></th><?php endforeach;?><th>Judge Total</th></tr></thead><tbody><?php foreach($entries as $entry):foreach($judges as $ji=>$judge):?><tr><td><?php if($ji===0):?><strong>#<?=(int)$entry['bib_number']?> <?=e($entry['display_name'])?></strong><?php endif;?></td><td><?=e($judge['judge_name'])?><?=$judge['is_chief']?' ★':''?></td><?php $sum=0;foreach($criteria as $x):$v=$marks[$entry['id']][$judge['id']][$x['id']]??'';$sum+=(float)$v;?><td><input class="form-control score-input" type="number" min="0" max="<?=e($x['maximum_points'])?>" step="0.01" name="mark[<?=$entry['id']?>][<?=$judge['id']?>][<?=$x['id']?>]" value="<?=e((string)$v)?>" <?=$locked?'disabled':''?>></td><?php endforeach;?><td><strong><?=number_format($sum,2)?></strong></td></tr><?php endforeach;endforeach;?></tbody></table></div><?php if(!$locked):?><div class="sticky-actions no-print"><button class="btn btn-outline-primary">Save Score Draft</button></div><?php endif;?></form><?php endif;?>
<div class="d-flex gap-2 flex-wrap no-print mt-3"><button class="btn btn-outline-dark" onclick="print()">Print Judge Sheet</button><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="calculate"><button class="btn btn-warning" <?=$locked?'disabled':''?>>Calculate Total &amp; Sort</button></form><form method="post" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="checkpoint"><input class="form-control" name="checkpoint_label" placeholder="Checkpoint name"><button class="btn btn-outline-success">Save Checkpoint</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="submit"><button class="btn btn-success" <?=$locked?'disabled':''?> onclick="return confirm('Submit and lock this competition?')">Submit Competition</button></form></div>
<h2 class="h5 mt-4">Calculated Results</h2><table class="table"><thead><tr><th>Place</th><th>Bib</th><th>Competitor</th><th>Total Score</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><strong><?=(int)$r['placement']?></strong></td><td><?=(int)$r['bib_number']?></td><td><?=e($r['display_name'])?></td><td><?=number_format((float)$r['total_score'],2)?></td></tr><?php endforeach;?><?php if(!$results):?><tr><td colspan="4" class="text-muted">Save scores, then calculate totals.</td></tr><?php endif;?></tbody></table><div class="no-print"><h2 class="h6 mt-4">Checkpoints</h2><?php foreach($checkpoints as $cp):?><span class="badge text-bg-light border me-2"><?=e($cp['label'])?> · <?=e($cp['created_at'])?></span><?php endforeach;?></div></div></section></main></body></html>
